import math

def is_power_of_six(N):
    if N <= 0:
        return False
    if N == 1:
        # 6^0 = 1, but we are looking for positive integer c, so c >= 1.
        # If S is 6-near, S = 6^c + 1, so S-1 = 6^c. If c=1, S-1=6.
        return False # Since we check S-1 and expect c >= 1

    base = 6
    power = 1
    while power <= N:
        if power == N:
            return True
        power *= base
    return False

# Candidates for B (2^a + 1, a in {1, 2, 3})
B_candidates = {
    2**1 + 1: 1, # B=3, a=1
    2**2 + 1: 2, # B=5, a=2
    2**3 + 1: 3  # B=9, a=3
}

# Candidates for T (3^b + 1, b in {1, 2, 3})
T_candidates = {
    3**1 + 1: 1, # T=4, b=1
    3**2 + 1: 2, # T=10, b=2
    3**3 + 1: 3  # T=28, b=3
}

solutions = []
for B, a in B_candidates.items():
    for T, b in T_candidates.items():
        S = B + T
        S_minus_1 = S - 1

        # Check if S is a 6-near number (S = 6^c + 1, c >= 1)
        if is_power_of_six(S_minus_1):
            # We found a solution (B, T, S)
            solutions.append((B, T, S))

print("Solutions found (B, T, S):")
for sol in solutions:
    print(sol)

# Calculate the sum of all elements in all solutions
total_sum = 0
for B, T, S in solutions:
    total_sum += (B + T + S)

print("\nTotal sum of (B+T+S) for all solutions:", total_sum)

